def _binom_table():
    b = [[0] * 6 for _ in range(36)]
    for n in range(36):
        b[n][0] = 1
    for n in range(1, 36):
        for k in range(1, 6):
            b[n][k] = b[n - 1][k - 1] + b[n - 1][k]
    return b


_BINOM = _binom_table()
_PREFLOP_B64 = ""


def _load_preflop():
    blob = zlib.decompress(base64.b64decode(_PREFLOP_B64))
    data = array.array("H")
    data.frombytes(blob)
    if array.array("H", [1]).tobytes()[0] != 1:
        data.byteswap()
    if len(data) != 376992:
        raise RuntimeError("bad preflop table")
    return data


_PREFLOP = _load_preflop()

