def _charge(memory, started):
    memory["t_used"] = memory.get("t_used", 0.0) + (time.perf_counter() - started)


def _rank5(cards):
    b = _BINOM
    a, c, d, e, f = cards
    return b[a][1] + b[c][2] + b[d][3] + b[e][4] + b[f][5]


def _equity_lookup(cards):
    c = cards if (len(cards) == 5 and cards[0] < cards[1] < cards[2] < cards[3] < cards[4]) else tuple(sorted(cards))
    return _PREFLOP[_rank5(c)] / 100.0



# The searched policy, inlined. This file imports only evaluator.py and game.py.

def _preflop_eq(cards) -> float:
    """Showdown equity versus a random hand, on a 0 to 1 scale."""
    return _equity_lookup(cards) / 100.0

