class Params:
    """One numeric threshold per entry of :data:`SPEC`."""

    __slots__ = tuple(row[0] for row in SPEC)

    def __init__(self, values: dict[str, float] | None = None) -> None:
        src = values or {}
        for name, lo, hi, default in SPEC:
            v = float(src.get(name, default))
            if v < lo:
                v = lo
            elif v > hi:
                v = hi
            setattr(self, name, v)
        self._sanitize()

    def _sanitize(self) -> None:
        """Keep 'bigger bet requires a stronger hand' even if the search crosses them."""
        if self.pf_open_pot < self.pf_open_half:
            self.pf_open_pot = self.pf_open_half
        if self.pf_bb_pot < self.pf_bb_half:
            self.pf_bb_pot = self.pf_bb_half
        if self.pf_3bet_pot < self.pf_3bet_half:
            self.pf_3bet_pot = self.pf_3bet_half
        for pot_name, half_name in zip(_BET_POT, _BET_HALF):
            if getattr(self, pot_name) < getattr(self, half_name):
                setattr(self, pot_name, getattr(self, half_name))
        if self.raise_pot < self.raise_half:
            self.raise_pot = self.raise_half

    def to_dict(self) -> dict[str, float]:
        return {name: round(float(getattr(self, name)), 5) for name, *_ in SPEC}

    def vector(self) -> list[float]:
        return [float(getattr(self, name)) for name, *_ in SPEC]


class HandRead:
    """What the bot knows about its hand on the current board."""

    __slots__ = ("category", "top", "fd", "nfd", "sd", "paired", "flushy", "mono", "straighty")

    def __init__(self) -> None:
        self.category = 0
        self.top = 0
        self.fd = 0
        self.nfd = 0
        self.sd = 0
        self.paired = False
        self.flushy = False
        self.mono = False
        self.straighty = False


def _table() -> dict[int, int]:
    global _SCORE_TABLE
    if _SCORE_TABLE is None:
        warmup()
        _SCORE_TABLE = get_table()
    return _SCORE_TABLE


def current_score(hole, board) -> int:
    """Best made hand using exactly 2 hole cards and 3 board cards.

    Works on the flop (3), turn (4) and river (5). Higher is better.
    The category is ``score >> 20`` (0 high card ... 8 straight flush).
    """
    table = _table()
    hb = [1 << c for c in hole]
    hms = [hb[i] | hb[j] for i, j in _PAIRS]
    bb = [1 << c for c in board]
    n = len(board)
    best = 0
    if n == 5:
        trips = _TRIPS5
    elif n == 4:
        trips = _TRIPS4
    elif n == 3:
        bm = bb[0] | bb[1] | bb[2]
        for hm in hms:
            score = table[hm | bm]
            if score > best:
                best = score
        return best
    else:
        return 0
    for i, j, k in trips:
        bm = bb[i] | bb[j] | bb[k]
        for hm in hms:
            score = table[hm | bm]
            if score > best:
                best = score
    return best


def analyze(hole, board) -> HandRead:
    """Made-hand category plus flush draws, straight draws and board texture."""
    hs = HandRead()
    if len(board) < 3 or len(hole) != 5:
        return hs
    score = current_score(hole, board)
    hs.category = score >> 20
    hs.top = (score >> 16) & 0xF

    suit_count = [0, 0, 0, 0]
    suit_ranks: list[list[int]] = [[], [], [], []]
    rank_count = [0] * 9
    bset: set[int] = set()
    for c in board:
        r = c >> 2
        s = c & 3
        suit_count[s] += 1
        suit_ranks[s].append(r)
        rank_count[r] += 1
        bset.add(r)
    hole_suit: list[list[int]] = [[], [], [], []]
    hset: set[int] = set()
    for c in hole:
        r = c >> 2
        hole_suit[c & 3].append(r)
        hset.add(r)

    best_fd = 0
    nut = 0
    for s in range(4):
        hc = len(hole_suit[s])
        if hc < 2:
            continue
        bc = suit_count[s]
        if bc >= 3:
            level = 3
        elif bc == 2 and len(board) < 5:
            level = 2
        elif bc == 1 and len(board) <= 3:
            level = 1
        else:
            level = 0
        if level > best_fd:
            best_fd = level
        if level >= 2:
            blocked = set(suit_ranks[s])
            top_live = None
            for r in range(8, -1, -1):
                if r not in blocked:
                    top_live = r
                    break
            if top_live is not None and top_live in hole_suit[s]:
                nut = 1
    hs.fd = best_fd
    hs.nfd = nut

    sd = 0
    for window in _WINDOWS:
        have = len(hset & window)
        if have < 2:
            continue
        need = 3 - len(bset & window)
        if need == 1:
            sd = 2
            break
        if need == 2 and len(board) <= 3 and sd < 1:
            sd = 1
    # A made straight is already in the category. Don't also pay a draw bonus.
    if hs.category >= 3 and sd:
        sd = 0
    hs.sd = sd

    hs.paired = any(n >= 2 for n in rank_count)
    max_suit = max(suit_count)
    hs.flushy = max_suit >= 3
    hs.mono = len(board) == 3 and max_suit == 3
    for window in _WINDOWS:
        if len(bset & window) >= 3:
            hs.straighty = True
            break
    return hs


def base_equity(street: int, category: int, fd: int) -> float:
    """Equity prior for this made hand and flush draw, before texture tweaks."""
    buckets = BUCKETS
    if buckets:
        key = ("preflop", "flop", "turn", "river")[int(street)]
        table = buckets.get(key)
        if table is not None and 0 <= category < len(table):
            row = table[category]
            idx = fd if fd < len(row) else len(row) - 1
            value = row[idx]
            if value is not None:
                return float(value)
    base = _DEFAULT_BASE[category if 0 <= category <= 8 else 0]
    if fd == 2:
        base += 0.10
    elif fd == 1:
        base += 0.03
    return base


def equity_proxy(hs: HandRead, params: Params, street: int) -> float:
    """Turn a hand read into a single equity number in (0, 1)."""
    eq = base_equity(street, hs.category, hs.fd if hs.fd < 3 else 0)
    # A made flush is already inside the category prior. Nut flushes still win more.
    if hs.nfd and hs.fd >= 2 and hs.category < FOUR_OF_A_KIND:
        eq += params.nfd_bonus
    if hs.category < 3:
        if hs.sd == 2:
            eq += params.sd_bonus
        elif hs.sd == 1:
            eq += params.sd_bonus * 0.4
    if hs.category <= 4:
        scale = 1.0 if hs.category <= 2 else 0.55
        eq += params.kicker_bonus * ((hs.top / 8.0) - 0.5) * scale
    if hs.paired and hs.category <= 3:
        eq -= params.pair_penalty
    if hs.flushy and hs.category < FLUSH:
        eq -= params.flush_threat_penalty
        if hs.mono:
            eq -= params.mono_penalty
    if hs.straighty and hs.category < 3:
        eq -= params.straight_threat_penalty
    if eq < 0.02:
        return 0.02
    if eq > 0.98:
        return 0.98
    return eq


def mc_equity(hole, board, rng: random.Random, samples: int) -> float:
    """Monte Carlo equity of ``hole`` on ``board`` versus a random opponent hand."""
    if samples <= 0:
        return 0.5
    dead = 0
    for c in hole:
        dead |= 1 << c
    for c in board:
        dead |= 1 << c
    deck = [c for c in range(36) if (dead & (1 << c)) == 0]
    need_board = 5 - len(board)
    need = 5 + need_board
    length = len(deck)
    wins = 0.0
    board_t = tuple(board)
    for _ in range(samples):
        for i in range(need):
            j = rng.randrange(i, length)
            deck[i], deck[j] = deck[j], deck[i]
        if need_board:
            full = board_t + tuple(deck[5:need])
        else:
            full = board_t
        s1 = omaha_score(hole, full)
        s2 = omaha_score(deck[0:5], full)
        if s1 > s2:
            wins += 1.0
        elif s1 == s2:
            wins += 0.5
    return wins / samples


def init_memory(memory: dict, seed: int = 0x5DE7) -> None:
    """Fill every key a half is allowed to carry. Called from ``new_half``."""
    memory["rng"] = random.Random(seed)
    memory["hands_done"] = 0
    memory["cur_hand"] = -1
    memory["seen"] = 0
    memory["opp_raises"] = 0
    memory["opp_pf_raises"] = 0
    memory["opp_calls"] = 0
    memory["opp_checks"] = 0
    memory["opp_folds"] = 0
    memory["opp_pf_folds"] = 0
    memory["sd_n"] = 0
    memory["sd_cat"] = 0
    memory["think"] = 0.0
    memory["internal_errors"] = 0
    memory["last_hist"] = ()
    memory["river_bluff_sd"] = 0
    memory["river_value_sd"] = 0


def observe(obs, memory: dict) -> None:
    """Count opponent raises, calls and checks from the part of the history we have not seen."""
    if memory["cur_hand"] != obs.hand_index:
        memory["cur_hand"] = obs.hand_index
        memory["seen"] = 0
    hist = obs.action_history
    seen = memory["seen"]
    if seen < 0 or seen > len(hist):
        seen = 0
    for action in hist[seen:]:
        if action.is_me:
            continue
        if action.action == Action.RAISE_HALF or action.action == Action.RAISE_POT:
            memory["opp_raises"] += 1
            if action.street == Street.PREFLOP:
                memory["opp_pf_raises"] += 1
        elif action.action == Action.CHECK_CALL:
            if action.amount > 0:
                memory["opp_calls"] += 1
            else:
                memory["opp_checks"] += 1
    memory["seen"] = len(hist)
    memory["last_hist"] = tuple(
        (int(a.street), bool(a.is_me), int(a.action), int(a.amount)) for a in hist
    )


def update_hand(result, memory: dict) -> None:
    """Learn a fold or a showdown. Folds are not in ``action_history`` (the hand is already over)."""
    memory["hands_done"] += 1
    if result.went_to_showdown and result.opp_hole is not None and len(result.board) == 5:
        cat = omaha_score(result.opp_hole, result.board) >> 20
        memory["sd_n"] += 1
        memory["sd_cat"] += cat
        bet_river = any(
            (not is_me) and street == int(Street.RIVER) and act in (int(Action.RAISE_HALF), int(Action.RAISE_POT))
            for street, is_me, act, _amount in memory.get("last_hist") or ()
        )
        if bet_river:
            if cat <= ONE_PAIR:
                memory["river_bluff_sd"] += 1
            else:
                memory["river_value_sd"] += 1
    elif (not result.went_to_showdown) and result.winner == "me":
        memory["opp_folds"] += 1
        if len(result.board) == 0:
            memory["opp_pf_folds"] += 1
    memory["last_hist"] = ()


def exploit_adjust(memory: dict, params: Params) -> tuple[float, float, float, float]:
    """Return (open_shift, bluff_mult, value_shift, call_shift).

    Shifts stay at zero until 80 hands, and they only get large against a
    clearly unbalanced opponent. A balanced bot is aggressive with value, so
    raw aggression never loosens calls. Call-downs require showdowns where
    they bet the river and showed one pair or worse.
    """
    if memory["hands_done"] < max(80, int(params.min_hands)):
        return 0.0, 1.0, 0.0, 0.0
    folds = memory["opp_folds"]
    calls = memory["opp_calls"]
    faced = folds + calls
    fold_rate = (folds / faced) if faced >= 20 else 0.42
    raises = memory["opp_raises"]
    passive = memory["opp_checks"] + memory["opp_calls"]
    acted = raises + passive
    agg = (raises / acted) if acted >= 20 else 0.40
    sd_n = memory["sd_n"]
    avg_cat = (memory["sd_cat"] / sd_n) if sd_n >= 8 else 3.2
    hands = max(1, memory["hands_done"])
    pf_fold_rate = memory["opp_pf_folds"] / hands

    # Near equilibrium: fold rate around 40% and showdown hands that are real.
    balanced = 0.32 <= fold_rate <= 0.55 and avg_cat >= 2.6 and sd_n >= 8
    open_shift = 0.0 if balanced else -params.pf_steal * max(0.0, pf_fold_rate - 0.15)
    bluff_mult = 1.0
    value_shift = 0.0
    call_shift = 0.0
    if not balanced and fold_rate > 0.58 and faced >= 24:
        bluff_mult = min(1.8, 1.0 + params.bluff_vs_folder * (fold_rate - 0.50) * 0.35)
    if not balanced and fold_rate < params.station_fold_rate and faced >= 24:
        bluff_mult = 0.25
        value_shift -= min(0.08, params.thin_value * (params.station_fold_rate - fold_rate))
    bluff_shows = memory.get("river_bluff_sd", 0)
    value_shows = memory.get("river_value_sd", 0)
    shown = bluff_shows + value_shows
    if shown >= 6 and bluff_shows / shown >= 0.45:
        call_shift -= min(0.05, params.calldown_vs_aggro * 0.12)
    if sd_n >= 8 and avg_cat > 4.2 and agg > 0.35:
        call_shift += min(0.06, params.tighten_vs_nit * (avg_cat - 4.0))
    if bluff_mult < 0.20:
        bluff_mult = 0.20
    elif bluff_mult > 1.8:
        bluff_mult = 1.8
    return open_shift, bluff_mult, value_shift, call_shift


def _clamp(value: float, lo: float, hi: float) -> float:
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value


def _pick(legal, *prefs: Action) -> Action:
    for action in prefs:
        if action in legal:
            return action
    return legal[0]


def _all_in(obs, action: Action) -> bool:
    total = obs.raise_to.get(action)
    if total is None:
        return False
    return total >= obs.my_bet + obs.my_stack


def _price(obs) -> float:
    if obs.to_call <= 0:
        return 0.0
    return obs.to_call / (obs.pot + obs.to_call)


def _bet_ratio(obs) -> float:
    """How big the bet we face is, compared with the pot before that bet."""
    if obs.to_call <= 0:
        return 0.0
    before = obs.pot - obs.to_call
    if before <= 0:
        return 1.0
    return obs.to_call / before


def _we_bet(obs, street: Street) -> bool:
    return any(
        action.is_me and action.street == street and action.action in (Action.RAISE_HALF, Action.RAISE_POT)
        for action in obs.action_history
    )


def _hole_shape(hole) -> tuple[bool, bool, bool, bool]:
    """(double suited, suited ace, three of one suit, connected).

    Lautaro Guerra and Ka Kwan Lau stack off double-suited aces and connected
    hands that can make the nuts. Three of one suit cannot make a better flush
    than two, so that hand is dominated once a raise comes in.
    """
    counts = [0, 0, 0, 0]
    by_suit: list[list[int]] = [[], [], [], []]
    ranks: list[int] = []
    for card in hole:
        suit = card & 3
        rank = card >> 2
        counts[suit] += 1
        by_suit[suit].append(rank)
        ranks.append(rank)
    double = sum(count >= 2 for count in counts) >= 2
    suited_ace = any(8 in by_suit[suit] and len(by_suit[suit]) >= 2 for suit in range(4))
    three = max(counts) >= 3
    unique = sorted(set(ranks))
    if 8 in unique and min(unique) <= 3:
        connected = sum(1 for rank in unique if rank <= 3 or rank == 8) >= 4
    else:
        connected = len(unique) >= 4 and unique[-1] - unique[0] <= 4
    return double, suited_ace, three, connected


def _blocks_nut_straight(hole, board, category: int) -> bool:
    """We hold the one rank that completes the highest straight, and we do not have it.

    Stephen Chidwick calls a bluff-catcher when that card is in his hand,
    because the bettor has fewer combinations of the nuts.
    """
    if len(board) < 4 or category >= STRAIGHT:
        return False
    board_ranks = {card >> 2 for card in board}
    hole_ranks = {card >> 2 for card in hole}

    def height(window: frozenset) -> int:
        if 8 in window and 0 in window:
            return -1
        return max(window)

    for window in sorted(_WINDOWS, key=height, reverse=True):
        missing = window - board_ranks
        if len(window & board_ranks) >= 4 and len(missing) == 1 and missing <= hole_ranks:
            return True
    return False


def _nut_blocker_bluff(hole, board) -> bool:
    """One ace of a suit the board has three or more of, and we cannot have the flush.

    Shaun Deeb's blocker bluff: the ace removes the nuts, and in Omaha a single
    suited ace does not give us a flush (that needs two hole cards of the suit).
    """
    if len(board) < 3:
        return False
    suit_board = [0, 0, 0, 0]
    for card in board:
        suit_board[card & 3] += 1
    suit_hole = [[] for _ in range(4)]
    for card in hole:
        suit_hole[card & 3].append(card >> 2)
    for suit in range(4):
        if suit_board[suit] >= 3 and len(suit_hole[suit]) == 1 and 8 in suit_hole[suit]:
            return True
    return False


def _has_flush_redraw(hole, board) -> bool:
    """Two hole cards of a suit that already has two on the board but not three."""
    if len(board) >= 5:
        return False
    suit_board = [0, 0, 0, 0]
    suit_hole = [0, 0, 0, 0]
    for card in board:
        suit_board[card & 3] += 1
    for card in hole:
        suit_hole[card & 3] += 1
    return any(suit_board[suit] == 2 and suit_hole[suit] >= 2 for suit in range(4))


def _opp_line(obs) -> str:
    """strong: they bet the turn and the river. bet: they bet this street. checked: they checked to us."""
    bet_turn = False
    bet_street = False
    checked = False
    for action in obs.action_history:
        if action.is_me:
            continue
        if action.action in (Action.RAISE_HALF, Action.RAISE_POT):
            if action.street == Street.TURN:
                bet_turn = True
            if action.street == obs.street:
                bet_street = True
        elif action.action == Action.CHECK_CALL and action.amount == 0 and action.street == obs.street:
            checked = True
    if bet_turn and bet_street and obs.street == Street.RIVER:
        return "strong"
    if bet_street:
        return "bet"
    if checked:
        return "checked"
    return "unknown"


def range_equity(hole, board, rng: random.Random, samples: int, min_cat: int | None) -> float | None:
    """Fraction of a filtered opponent range we beat on this exact board.

    min_cat keeps only hands whose current Omaha category is at least that
    strong, so a turn-and-river bettor is not treated as a random hand.
    Returns None if too few samples survive the filter.
    """
    if samples <= 0 or len(board) != 5:
        return None
    dead = 0
    for card in hole:
        dead |= 1 << card
    for card in board:
        dead |= 1 << card
    deck = [card for card in range(36) if (dead & (1 << card)) == 0]
    if len(deck) < 5:
        return None
    board_t = tuple(board)
    wins = 0.0
    used = 0
    tries = 0
    limit = samples * (5 if min_cat is not None else 1)
    while used < samples and tries < limit:
        tries += 1
        opp = rng.sample(deck, 5)
        if min_cat is not None and (current_score(opp, board_t) >> 20) < min_cat:
            continue
        s1 = omaha_score(hole, board_t)
        s2 = omaha_score(opp, board_t)
        used += 1
        if s1 > s2:
            wins += 1.0
        elif s1 == s2:
            wins += 0.5
    if used < 4:
        return None
    return wins / used


def decide(obs, memory: dict, params: Params, exploit: bool = True,
           eq_override: float | None = None) -> Action:
    """Choose an action from ``obs.legal_actions``."""
    observe(obs, memory)
    if exploit:
        open_shift, bluff_mult, value_shift, call_shift = exploit_adjust(memory, params)
    else:
        open_shift, bluff_mult, value_shift, call_shift = 0.0, 1.0, 0.0, 0.0

    if obs.street == Street.PREFLOP or len(obs.board) < 3:
        eq = _preflop_eq(obs.hole_cards)
        return _preflop(obs, eq, params, open_shift, call_shift)

    hs = analyze(obs.hole_cards, obs.board)
    if eq_override is None:
        eq = equity_proxy(hs, params, int(obs.street))
    else:
        eq = _clamp(eq_override, 0.02, 0.98)
    return _postflop(obs, eq, hs, params, bluff_mult, value_shift, call_shift, memory["rng"])


def _preflop(obs, eq: float, params: Params, open_shift: float, call_shift: float) -> Action:
    legal = obs.legal_actions
    double, suited_ace, three, connected = _hole_shape(obs.hole_cards)
    # Hands that can make the nut flush or a nut wrap are the ones these players
    # take to a big pot. A three-suited hand is the one they release.
    if double and (suited_ace or connected):
        eq = _clamp(eq + 0.015, 0.02, 0.99)
    elif suited_ace and connected:
        eq = _clamp(eq + 0.010, 0.02, 0.99)
    if three:
        eq = _clamp(eq - 0.025, 0.02, 0.99)
    # No raise yet: button is completing the small blind, or the big blind has the option.
    if obs.raises_this_street == 0:
        if obs.to_call == 0:
            if eq >= params.pf_bb_pot + open_shift and Action.RAISE_POT in legal:
                return Action.RAISE_POT
            if eq >= params.pf_bb_half + open_shift and Action.RAISE_HALF in legal:
                return Action.RAISE_HALF
            return Action.CHECK_CALL
        # One chip to the button. Even a weak hand is priced in; raise the good ones.
        if eq >= params.pf_open_pot + open_shift and Action.RAISE_POT in legal:
            return Action.RAISE_POT
        if eq >= params.pf_open_half + open_shift and Action.RAISE_HALF in legal:
            return Action.RAISE_HALF
        return Action.CHECK_CALL

    tight = params.pf_reraise_tighten * (obs.raises_this_street - 1)
    tight += max(0.0, call_shift) * 0.5
    if eq >= params.pf_3bet_pot + tight + open_shift and Action.RAISE_POT in legal:
        if not (_all_in(obs, Action.RAISE_POT) and eq < params.commit_eq):
            return Action.RAISE_POT
    if eq >= params.pf_3bet_half + tight + open_shift and Action.RAISE_HALF in legal:
        if not (_all_in(obs, Action.RAISE_HALF) and eq < params.commit_eq):
            return Action.RAISE_HALF
    price = _price(obs)
    margin = params.pf_call_margin + tight + call_shift
    # Three of one suit cannot make a better flush than two, and the extra
    # card is one of our own outs. Don't continue for a big price with it.
    suit_counts = [0, 0, 0, 0]
    for card in obs.hole_cards:
        suit_counts[card & 3] += 1
    if max(suit_counts) >= 3 and obs.raises_this_street >= 1:
        margin += 0.045
    # Deeb: a bare rundown is not a 3-bet continue. Suited aces and
    # double-suited connectors are.
    if obs.raises_this_street >= 2 and not (suited_ace or (double and connected)):
        margin += 0.035
    if obs.to_call >= obs.my_stack:
        margin = min(margin, 0.0)
    if eq >= price + margin:
        return Action.CHECK_CALL
    if Action.FOLD in legal:
        return Action.FOLD
    return Action.CHECK_CALL


def _postflop(obs, eq: float, hs: HandRead, params: Params, bluff_mult: float,
              value_shift: float, call_shift: float, rng: random.Random) -> Action:
    legal = obs.legal_actions
    cat = hs.category
    # Quads or better are the nuts for practical purposes. Always put chips in.
    if cat >= FOUR_OF_A_KIND:
        return _pick(legal, Action.RAISE_POT, Action.RAISE_HALF, Action.CHECK_CALL)

    idx = int(obs.street) - 1
    if idx < 0:
        idx = 0
    elif idx > 2:
        idx = 2
    # In position, bet and call a little wider. This is not a searched parameter.
    pos = -0.015 if obs.is_button else 0.012
    line = _opp_line(obs)
    # On the river, replace raw equity with equity against the line's range.
    # A half-pot value bet has to beat about 58% of the hands that call.
    if idx == 2:
        if line == "strong":
            min_cat = THREE_OF_A_KIND
        elif line == "bet":
            min_cat = TWO_PAIR
        else:
            min_cat = TWO_PAIR
        sampled = range_equity(obs.hole_cards, obs.board, rng, 10, min_cat)
        if sampled is not None:
            eq = 0.7 * sampled + 0.3 * eq

    def _commit_ok(action: Action, equity: float) -> bool:
        # Small bets are not a stack commitment. All-ins are.
        if not _all_in(obs, action):
            return True
        floor = max(params.commit_eq, 0.66)
        if idx == 1:
            floor = max(floor, 0.72)
        elif idx == 2:
            floor = max(floor, 0.74)
        if equity >= floor or cat >= FLUSH:
            return True
        return bool(hs.nfd and hs.fd == 2 and equity >= _price(obs) + 0.10)

    if obs.to_call == 0:
        pot_th = _clamp(getattr(params, _BET_POT[idx]) + value_shift + pos, 0.35, 0.95)
        half_th = _clamp(getattr(params, _BET_HALF[idx]) + value_shift + pos, 0.28, pot_th)
        if idx == 2:
            # No thin value against a range that continues. Stations still get a small discount.
            half_th = max(half_th, 0.58 + min(0.0, value_shift))
            pot_th = max(pot_th, 0.70)
            # Chidwick: a turn barrel needs a river plan. A weak pair has neither
            # showdown value against a caller nor a credible bluff.
            if _we_bet(obs, Street.TURN) and cat <= TWO_PAIR and eq < 0.55:
                if cat <= ONE_PAIR and _nut_blocker_bluff(obs.hole_cards, obs.board) and rng.random() < 0.25 * bluff_mult:
                    if Action.RAISE_HALF in legal and not _all_in(obs, Action.RAISE_HALF):
                        return Action.RAISE_HALF
                return Action.CHECK_CALL
            # A non-nut flush on a four-flush only gets called by a better flush
            # if the bet is the size of the pot. Half pot still gets paid by worse.
            if cat == FLUSH and hs.flushy and not hs.nfd:
                if value_shift < 0 and Action.RAISE_POT in legal and _commit_ok(Action.RAISE_POT, eq):
                    return Action.RAISE_POT
                if Action.RAISE_HALF in legal and _commit_ok(Action.RAISE_HALF, eq):
                    return Action.RAISE_HALF
        two_tone = len({card & 3 for card in obs.board}) <= 2
        # Dynamic means a flush can come, or a wrap and a flush draw live together.
        # A bare straight-possible flop is normal in a 36-card deck and is not,
        # by itself, the caller's board.
        dynamic = hs.mono or hs.flushy or (hs.straighty and two_tone)
        nut_draw = hs.nfd and hs.fd == 2
        # Turn: the flop bet needed a continue. A flush-possible turn without a
        # set or the nut draw is a give-up, not a second barrel.
        if idx == 1 and _we_bet(obs, Street.FLOP) and not nut_draw:
            if hs.flushy and cat < FLUSH:
                return Action.CHECK_CALL
            if hs.straighty and cat <= ONE_PAIR and hs.sd < 2:
                return Action.CHECK_CALL
        # Flop: do not open a pot on a board the caller can have the nuts on.
        if idx == 0 and dynamic and cat < THREE_OF_A_KIND and not nut_draw and not (
            hs.sd == 2 and _has_flush_redraw(obs.hole_cards, obs.board)
        ):
            if not (obs.is_button and cat >= ONE_PAIR and hs.fd >= 1):
                return Action.CHECK_CALL
        if eq >= pot_th and Action.RAISE_POT in legal and _commit_ok(Action.RAISE_POT, eq):
            return Action.RAISE_POT
        if eq >= half_th and Action.RAISE_HALF in legal and _commit_ok(Action.RAISE_HALF, eq):
            return Action.RAISE_HALF
        # Lau / Deeb: semi-bluff the nut flush draw, or a wrap that also has a flush redraw.
        # A naked straight draw does not get barreled. Lamb: don't commit the stack with it.
        semi_p = 0.0
        if hs.nfd and hs.fd == 2 and cat < 4:
            semi_p = min(params.semi_freq, 0.55)
        elif hs.sd == 2 and _has_flush_redraw(obs.hole_cards, obs.board) and cat < 3:
            semi_p = min(params.semi_freq, 0.22)
        if idx == 1 and cat == 3 and not _has_flush_redraw(obs.hole_cards, obs.board):
            semi_p = 0.0
        if semi_p and rng.random() < semi_p * bluff_mult:
            if Action.RAISE_HALF in legal and _commit_ok(Action.RAISE_HALF, eq):
                return Action.RAISE_HALF
        bluff_p = getattr(params, _BLUFF[idx]) * bluff_mult
        if idx == 2:
            bluff_p = min(bluff_p, 0.10 * bluff_mult)
            if _nut_blocker_bluff(obs.hole_cards, obs.board) and cat <= ONE_PAIR:
                bluff_p = max(bluff_p, 0.22 * bluff_mult)
        # Random air on a dynamic board is the bet a nutted range check-raises.
        if dynamic and not nut_draw and cat < THREE_OF_A_KIND:
            bluff_p = 0.0
        if eq < half_th - 0.08 and rng.random() < bluff_p:
            if Action.RAISE_HALF in legal and not _all_in(obs, Action.RAISE_HALF):
                return Action.RAISE_HALF
        return Action.CHECK_CALL

    price = _price(obs)
    ratio = _bet_ratio(obs)
    blocks_nuts = _nut_blocker_bluff(obs.hole_cards, obs.board) or _blocks_nut_straight(
        obs.hole_cards, obs.board, cat
    )
    # Out of position, raise sets and the nut draw into a single bet. That is
    # the pressure Deeb and Lamb put on a capped continuation range. A non-nut
    # flush does not raise: a better flush is the hand that calls.
    nutted = cat >= FOUR_OF_A_KIND or (cat >= FLUSH and hs.nfd) or (cat >= THREE_OF_A_KIND and not hs.flushy)
    if (not obs.is_button) and obs.raises_this_street == 1 and idx <= 1:
        if nutted or (hs.nfd and hs.fd == 2 and eq >= price + 0.06):
            if cat >= FLUSH and Action.RAISE_POT in legal and _commit_ok(Action.RAISE_POT, eq):
                return Action.RAISE_POT
            if Action.RAISE_HALF in legal and _commit_ok(Action.RAISE_HALF, eq):
                return Action.RAISE_HALF
    # A turn-and-river barrel is a nutted range in this game, because trips
    # beat a straight. Call a small one only with a card that blocks the nuts.
    if idx == 2 and _opp_line(obs) == "strong" and cat <= STRAIGHT:
        if blocks_nuts and ratio < 0.70 and eq + 0.02 >= price:
            return Action.CHECK_CALL
        if Action.FOLD in legal:
            return Action.FOLD
    margin = getattr(params, _CALL_M[idx]) + call_shift + (pos if obs.is_button else 0.0)
    if idx == 2 and ratio >= 0.65:
        margin = max(margin, 0.08)
    if obs.my_stack <= obs.to_call:
        margin = min(margin, 0.02)
        if idx == 1:
            margin = max(margin, 0.08)
    # A flush beats a full house here, but a non-nut flush still loses to a
    # higher flush. Lamb: do not raise a dominated flush into a big raise.
    if cat >= FLUSH and not hs.nfd and obs.raises_this_street >= 2 and ratio >= 0.55:
        if Action.FOLD in legal:
            return Action.FOLD
        return Action.CHECK_CALL
    # A flush beats a full house in this game. Never fold one to a single bet.
    if cat >= FLUSH:
        if eq >= params.raise_pot and Action.RAISE_POT in legal and _commit_ok(Action.RAISE_POT, eq):
            return Action.RAISE_POT
        if eq >= params.raise_half and Action.RAISE_HALF in legal and _commit_ok(Action.RAISE_HALF, eq):
            return Action.RAISE_HALF
        return Action.CHECK_CALL
    # Pot-sized river bet: one pair and weak two pair are not a bluff-catch
    # unless showdowns have already proved this opponent bluffs the river.
    if idx == 2 and ratio >= 0.65 and cat <= TWO_PAIR:
        # call_shift is already negative only when river bluffs have shown down.
        if call_shift >= -0.01 or cat <= ONE_PAIR or eq < price + margin:
            if Action.FOLD in legal:
                return Action.FOLD
    if eq >= params.raise_pot and Action.RAISE_POT in legal and _commit_ok(Action.RAISE_POT, eq):
        return Action.RAISE_POT
    if eq >= params.raise_half and Action.RAISE_HALF in legal and _commit_ok(Action.RAISE_HALF, eq):
        return Action.RAISE_HALF
    if eq + 1e-9 >= price + margin:
        return Action.CHECK_CALL
    if obs.to_call <= obs.big_blind and eq + 0.04 >= price:
        return Action.CHECK_CALL
    if Action.FOLD in legal:
        return Action.FOLD
    return Action.CHECK_CALL


def fallback_action(obs) -> Action:
    if Action.CHECK_CALL in obs.legal_actions:
        return Action.CHECK_CALL
    if Action.FOLD in obs.legal_actions:
        return Action.FOLD
    return obs.legal_actions[0]



