_PARAMS = Params(CHAMPION_PARAMS)


def new_half(config: AgentConfig, memory: dict) -> None:
    started = time.perf_counter()
    try:
        init_memory(memory)
    except Exception:
        memory.clear()
        init_memory(memory)
    finally:
        _charge(memory, started)


def choose_action(obs: Observation, memory: dict) -> Action:
    started = time.perf_counter()
    try:
        if "rng" not in memory:
            init_memory(memory)
        action = decide(obs, memory, _PARAMS, exploit=True)
        if action not in obs.legal_actions:
            action = fallback_action(obs)
        return action
    except Exception:
        return fallback_action(obs)
    finally:
        _charge(memory, started)


def on_hand_end(result: HandResult, memory: dict) -> None:
    started = time.perf_counter()
    try:
        if "rng" not in memory:
            init_memory(memory)
        update_hand(result, memory)
    except Exception:
        return
    finally:
        _charge(memory, started)

